#include <iostream>
#include <string_view>

struct Printable { virtual std::string_view print() const = 0; virtual ~Printable() = default; };
struct Identifiable { virtual int id() const = 0; virtual ~Identifiable() = default; };
struct Item final : Printable, Identifiable {
    std::string_view print() const override { return "item"; }
    int id() const override { return 17; }
};
int main() { Item item; std::cout << item.print() << ':' << item.id() << '\n'; }
